function uid() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
}

function resizeImage(file, maxDim = 1000, quality = 0.72) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        let { width, height } = img;
        if (width > height && width > maxDim) {
          height = Math.round((height * maxDim) / width);
          width = maxDim;
        } else if (height > maxDim) {
          width = Math.round((width * maxDim) / height);
          height = maxDim;
        }
        const canvas = document.createElement("canvas");
        canvas.width = width;
        canvas.height = height;
        canvas.getContext("2d").drawImage(img, 0, 0, width, height);
        resolve(canvas.toDataURL("image/jpeg", quality));
      };
      img.onerror = reject;
      img.src = e.target.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

/* ---------------- Premium card press interaction (depth only) ---------------- */
function useCardFX() {
  const [pressed, setPressed] = useState(false);

  const handlers = {
    onPointerDown: () => setPressed(true),
    onPointerUp: () => setPressed(false),
    onPointerLeave: () => setPressed(false),
    onPointerCancel: () => setPressed(false),
  };

  return { pressed, handlers };
}

/* ---------------- Sub-page Header (Novo Relatório, Histórico, módulos) ---------------- */
function Header({ title, onBack, onMenu }) {
  const [pressionado, setPressionado] = useState(false);
  return (
    <div
      style={{
        height: 72,
        flexShrink: 0,
        display: "flex",
        alignItems: "center",
        gap: 12,
        padding: "0 16px",
        background: "#000000",
        borderBottom: "1px solid #1C1C1C",
        position: "sticky",
        top: 0,
        zIndex: 20,
      }}
    >
      <button
        onClick={onBack || onMenu}
        onPointerDown={() => setPressionado(true)}
        onPointerUp={() => setPressionado(false)}
        onPointerLeave={() => setPressionado(false)}
        aria-label={onBack ? "Voltar" : "Menu"}
        style={{
          background: "#0D0D0E",
          border: "1px solid rgba(201,162,75,0.28)",
          borderRadius: 9,
          width: 32,
          height: 32,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          color: "#C9A24B",
          flexShrink: 0,
          transform: pressionado ? "scale(0.92)" : "scale(1)",
          transition: "transform 120ms ease, border-color 120ms ease",
        }}
      >
        {onBack ? <ChevronLeft size={17} /> : <Menu size={16} />}
      </button>
      <div style={{ lineHeight: 1.1 }}>
        <div
            style={{
              fontFamily: "'Roboto',sans-serif",
              fontWeight: 600,
              letterSpacing: 0.5,
              fontSize: 17,
              color: "#F3F3F1",
              textTransform: "uppercase",
            }}
          >
            {title}
        </div>
        <div
          style={{
            fontFamily: "'JetBrains Mono',monospace",
            fontSize: 10,
            color: "#7A7A7A",
            letterSpacing: 1,
          }}
        >
          ALLA CHECK
        </div>
      </div>
    </div>
  );
}

